45	    private String addressLine2;
46	
47	    @Column(name = "city")
48	    @NotEmpty
49	    private String city;
50	
51	    @Column(name = "telephone")
52	    @NotEmpty
53	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be a valid E.164 number")
54	    private String telephone;
55	
56	    @Column(name = "email")
57	    private String email;
58	
59	    @Column(name = "postcode")
60	    private String postcode;
61	
62	    @Column(name = "title")
63	    private String title;
64	
65	    @Column(name = "customer_code")
66	    private String customerCode;
67	
68	    @Column(name = "household_id")
69	    private String householdId;
70	
71	    @Column(name = "household_member_count")
72	    private Integer householdMemberCount;
73	
74	    @Column(name = "membership_level_cap")
75	    private Integer membershipLevelCap;
76	
77	    @Column(name = "namesake_count")
78	    private Integer namesakeCount;
79	
80	    @Column(name = "registration_date")
81	    private java.time.LocalDate registrationDate;
82	
83	    @Column(name = "birth_date")
84	    private java.time.LocalDate birthDate;
85	
86	    @Column(name = "bulk_signup_warning")
87	    private Boolean bulkSignupWarning;
88	
89	    @Column(name = "capacity_warning")
90	    private Boolean capacityWarning;
91	
92	    @Column(name = "possible_duplicate_of")
93	    private Integer possibleDuplicateOf;
94	
95	    @Column(name = "deleted")
96	    private Boolean deleted;
97	
98	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
99	    private Set<Pet> pets;
100	
101	    @PrePersist
102	    private void defaultRegistrationDate() {
103	        if (this.registrationDate == null) {
104	            this.registrationDate = java.time.LocalDate.now();
105	        }
106	    }
107	
108	    public java.time.LocalDate getRegistrationDate() {
109	        return this.registrationDate;
110	    }
111	
112	    /** True when more than 80 owners were already created on this owner's registration date. */
113	    public Boolean getBulkSignupWarning() {
114	        return this.bulkSignupWarning != null && this.bulkSignupWarning;
115	    }
116	
117	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
118	        this.bulkSignupWarning = bulkSignupWarning;
