120	
121	    /** True when this owner's city already held 40-49 owners (approaching the 50 capacity limit) at create time. */
122	    public Boolean getCapacityWarning() {
123	        return this.capacityWarning != null && this.capacityWarning;
124	    }
125	
126	    public void setCapacityWarning(boolean capacityWarning) {
127	        this.capacityWarning = capacityWarning;
