158	
159	    /** Assign this owner's customerCode, de-duplicated against {@code existing} (see {@link CustomerCodes}). */
160	    public void assignCustomerCode(Collection<Owner> existing) {
161	        this.customerCode = CustomerCodes.uniqueFor(this, existing);
