163	
164	    public Integer getNamesakeCount() {
165	        return this.namesakeCount;
166	    }
167	
168	    public void setNamesakeCount(Integer namesakeCount) {
169	        this.namesakeCount = namesakeCount;
170	    }
171	
172	    public Integer getHouseholdMemberCount() {
173	        return this.householdMemberCount;
174	    }
175	
176	    public void setHouseholdMemberCount(Integer householdMemberCount) {
177	        this.householdMemberCount = householdMemberCount;
178	    }
179	
180	    /** The membershipLevel ceiling this owner may reach, or null when uncapped. */
181	    public Integer getMembershipLevelCap() {
182	        return this.membershipLevelCap;
183	    }
184	
185	    public void setMembershipLevelCap(Integer membershipLevelCap) {
186	        this.membershipLevelCap = membershipLevelCap;
187	    }
188	
189	    public String getHouseholdId() {
190	        return this.householdId;
191	    }
192	
193	    public void setHouseholdId(String householdId) {
194	        this.householdId = householdId;
195	    }
196	
197	    /** The id of an existing owner this one softly matches, or null. */
198	    public Integer getPossibleDuplicateOf() {
199	        return this.possibleDuplicateOf;
200	    }
201	
202	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
203	        this.possibleDuplicateOf = possibleDuplicateOf;
204	    }
205	
206	    /** True when this owner softly matches an existing owner (see possibleDuplicateOf). */
207	    public boolean getPossibleDuplicate() {
