215	
216	    public void setDeleted(boolean deleted) {
217	        this.deleted = deleted;
218	    }
219	
220	    public String getPostcode() {
221	        return this.postcode;
222	    }
223	
224	    public void setPostcode(String postcode) {
225	        this.postcode = postcode;
