234	    }
235	
236	    public String getAddress() {
237	        return PostalAddress.compose(this.addressLine1, this.addressLine2, this.address);
238	    }
239	
240	    public void setAddress(String address) {
241	        this.address = PostalAddress.normalize(address);
242	    }
243	
244	    public String getAddressLine1() {
245	        return this.addressLine1;
246	    }
247	
248	    public void setAddressLine1(String addressLine1) {
249	        this.addressLine1 = PostalAddress.normalize(addressLine1);
250	    }
251	
252	    public String getAddressLine2() {
253	        return this.addressLine2;
254	    }
255	
256	    public void setAddressLine2(String addressLine2) {
257	        this.addressLine2 = PostalAddress.normalize(addressLine2);
258	    }
259	
260	    public String getCity() {
261	        return this.city;
262	    }
263	
264	    public void setCity(String city) {
265	        this.city = city;
266	    }
267	
268	    public String getTelephone() {
269	        return this.telephone;
270	    }
271	
272	    public void setTelephone(String telephone) {
273	        this.telephone = TelephoneNumber.toE164(telephone);
274	    }
275	
276	    protected Set<Pet> getPetsInternal() {
277	        if (this.pets == null) {
278	            this.pets = new HashSet<>();
279	        }
280	        return this.pets;
281	    }
282	
283	    protected void setPetsInternal(Set<Pet> pets) {
284	        this.pets = pets;
285	    }
286	
287	    public List<Pet> getPets() {
288	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
289	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
290	        return Collections.unmodifiableList(sortedPets);
291	    }
292	
293	    public void setPets(List<Pet> pets) {
294	        this.pets = new HashSet<>(pets);
295	    }
296	
297	    public void addPet(Pet pet) {
298	        getPetsInternal().add(pet);
299	        pet.setOwner(this);
300	    }
301	
302	    /**
303	     * Return the Pet with the given name, or null if none found for this Owner.
304	     *
305	     * @param name to test
306	     * @return true if pet name is already in use
307	     */
308	    public Pet getPet(String name) {
309	        return getPet(name, false);
310	    }
311	
312	    /**
313	     * Return the Pet with the given name, or null if none found for this Owner.
314	     *
315	     * @param name to test
316	     * @return true if pet name is already in use
317	     */
318	    public Pet getPet(String name, boolean ignoreNew) {
319	        name = name.toLowerCase();
320	        for (Pet pet : getPetsInternal()) {
321	            if (!ignoreNew || !pet.isNew()) {
322	                String compName = pet.getName();
323	                compName = compName.toLowerCase();
324	                if (compName.equals(name)) {
325	                    return pet;
326	                }
327	            }
328	        }
329	        return null;
330	    }
331	
332	    public Pet getPet(Integer petId) {
333	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
334	    }
335	
336	    @Override
337	    public String toString() {
338	        return new ToStringCreator(this)
339	
340	            .append("id", this.getId())
341	            .append("new", this.isNew())
342	            .append("lastName", this.getLastName())
343	            .append("firstName", this.getFirstName())
344	            .append("address", this.address)
345	            .append("city", this.city)
346	            .append("telephone", this.telephone)
347	            .toString();
348	    }
349	}
