1	package org.springframework.samples.petclinic.model;
2	
3	import java.util.concurrent.atomic.AtomicLong;
4	
5	import org.slf4j.Logger;
6	import org.slf4j.LoggerFactory;
7	
8	import org.springframework.samples.petclinic.mapper.OwnerSegments;
9	
10	/**
11	 * Emits the immutable structured {@code OWNER_CREATED} event to the dedicated
12	 * {@code AUDIT} logger, one per created owner, as a schema-version-2 JSON object
13	 * {@code {seq, ownerId, memberId, membershipLevel, ownerSegment, schemaVersion, event}}.
14	 * {@code seq} is a monotonically increasing integer across creates; {@code memberId} and
15	 * {@code ownerSegment} are recomputed from the owner's version-2 identity.
16	 *
17	 * <p>The event carries the owner's primary identifier — the memberId — via
18	 * {@link #primaryId(Owner)}.
19	 */
20	public final class OwnerCreatedEvent {
21	
22	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
23	
24	    private static final AtomicLong SEQ = new AtomicLong();
25	
26	    private OwnerCreatedEvent() {
27	    }
28	
29	    /** Emit the structured create event for {@code owner}. */
30	    public static void emit(Owner owner) {
31	        AUDIT.info(
32	            "{\"seq\":{},\"ownerId\":{},\"memberId\":\"{}\",\"membershipLevel\":{},"
33	                + "\"ownerSegment\":\"{}\",\"schemaVersion\":2,\"event\":\"OWNER_CREATED\"}",
34	            SEQ.incrementAndGet(), owner.getId(), primaryId(owner), MembershipLevels.levelOf(owner),
35	            OwnerSegments.of(owner));
36	    }
37	
38	    /** The owner's current primary identifier carried by the event. */
39	    private static String primaryId(Owner owner) {
40	        return owner.getCustomerCode();
41	    }
42	}
