3	import java.util.Map;
4	import java.util.concurrent.ConcurrentHashMap;
5	
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.web.context.request.RequestContextHolder;
8	import org.springframework.web.context.request.ServletRequestAttributes;
9	
10	/**
11	 * Idempotent-create rule for owners: a create carrying an {@code Idempotency-Key} header
12	 * is remembered under that key, so a repeat with the same key returns the originally
13	 * created owner instead of creating a duplicate.
14	 */
15	final class IdempotencyKeys {
16	
17	    private static final Map<String, Owner> SEEN = new ConcurrentHashMap<>();
18	
19	    private IdempotencyKeys() {
20	    }
21	
22	    /** The current request's {@code Idempotency-Key} header, or {@code null} when absent. */
23	    static String current() {
24	        if (RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes servlet) {
25	            return servlet.getRequest().getHeader("Idempotency-Key");
26	        }
27	        return null;
28	    }
29	
30	    /** The owner already created under {@code key}, or {@code null} when the key is new or absent. */
31	    static Owner seen(String key) {
32	        return key == null ? null : SEEN.get(key);
33	    }
34	
35	    /** Remember {@code owner} as the result created under {@code key} (a no-op when the key is absent). */
36	    static void remember(String key, Owner owner) {
37	        if (key != null) {
38	            SEEN.put(key, owner);
39	        }
40	    }
41	}
