1	package org.springframework.samples.petclinic.rest.controller.v1;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.Collection;
7	import java.util.Locale;
8	import java.util.OptionalInt;
9	
10	import org.springframework.samples.petclinic.model.MembershipLevels;
11	import org.springframework.samples.petclinic.model.Owner;
12	
13	/**
14	 * Household-identity rule for owners: two owners share a household when they have the
15	 * same last name and postcode. The householdId is derived deterministically from that
16	 * pair, so housemates share it automatically without any explicit link step.
17	 */
18	final class Households {
19	
20	    private Households() {
21	    }
22	
23	    /**
24	     * The deterministic household identifier: the first 12 hex characters of
25	     * SHA-256 over {@code normalizedLastName + '|' + postcode}.
26	     */
27	    static String idFor(Owner owner) {
28	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
29	        return sha256Hex12("V2|" + normalize(owner.getLastName()) + "|" + postcode);
30	    }
31	
32	    /**
33	     * Whether {@code candidate} lands in an existing owner's household and so should be
34	     * rejected as a duplicate. A {@code sharesHousehold} flag of {@code true} opts out,
35	     * declaring the candidate a member of that household instead.
36	     */
37	    static boolean isDuplicate(Collection<Owner> existing, Owner candidate, Boolean sharesHousehold) {
38	        if (Boolean.TRUE.equals(sharesHousehold)) {
39	            return false;
40	        }
41	        return hasHousemate(existing, candidate);
42	    }
43	
44	    /** Household size for {@code candidate}: its existing housemates plus itself. */
45	    static int size(Collection<Owner> existing, Owner candidate) {
46	        long housemates = existing.stream().filter(other -> sameHousehold(other, candidate)).count();
47	        return (int) housemates + 1;
48	    }
49	
50	    /**
51	     * The membershipLevel ceiling for {@code candidate}: one above the highest membershipLevel
52	     * among its existing household members, or {@code null} when it has no household member yet
53	     * (in which case no cap applies).
54	     */
55	    static Integer ceilingLevel(Collection<Owner> existing, Owner candidate) {
56	        OptionalInt max = existing.stream()
57	            .filter(other -> sameHousehold(other, candidate))
58	            .mapToInt(Households::effectiveLevel)
59	            .max();
60	        return max.isPresent() ? max.getAsInt() + 1 : null;
61	    }
62	
63	    /** An owner's membershipLevel after applying its own ceiling (see {@link #ceilingLevel}). */
64	    private static int effectiveLevel(Owner owner) {
65	        int level = MembershipLevels.levelOf(owner);
66	        Integer cap = owner.getMembershipLevelCap();
67	        return cap == null ? level : Math.min(level, cap);
68	    }
69	
70	    /** Whether an existing owner already belongs to {@code candidate}'s household. */
71	    static boolean hasHousemate(Collection<Owner> existing, Owner candidate) {
72	        return existing.stream().anyMatch(other -> sameHousehold(other, candidate));
73	    }
74	
75	    private static boolean sameHousehold(Owner a, Owner b) {
76	        return a.getHouseholdId() != null && a.getHouseholdId().equals(b.getHouseholdId());
77	    }
78	
79	    private static String normalize(String value) {
80	        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
81	    }
82	
83	    private static String sha256Hex12(String key) {
84	        try {
85	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
86	            StringBuilder hex = new StringBuilder(24);
87	            for (int i = 0; i < 6; i++) {
88	                hex.append(String.format("%02x", digest[i]));
89	            }
90	            return hex.toString();
91	        }
92	        catch (NoSuchAlgorithmException e) {
93	            throw new IllegalStateException(e);
94	        }
95	    }
96	}
