3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	import java.util.Set;
6	
7	import org.springframework.samples.petclinic.model.Owner;
8	
9	/**
10	 * Business-day rule for owner registration dates: the effective registration
11	 * date defaults to the server's current date when absent and, when it lands on
12	 * a weekend or a listed public holiday, rolls forward to the next business day.
13	 */
14	final class BusinessDays {
15	
16	    private static final Set<LocalDate> HOLIDAYS = Set.of(
17	        LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"), LocalDate.parse("2026-04-25"),
18	        LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
19	
20	    private BusinessDays() {
21	    }
22	
23	    /** The owner's effective registration date, defaulted and rolled onto a business day. */
24	    static LocalDate effective(Owner owner) {
25	        LocalDate date = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
26	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY
27	                || HOLIDAYS.contains(date)) {
28	            date = date.plusDays(1);
29	        }
30	        return date;
31	    }
32	}
