7	
8	/**
9	 * Identity rule for owners: every owner has one derived {@code identityKey} (see
10	 * {@link IdentityKeys}). A new owner duplicates an existing one only when their WHOLE
11	 * identityKey is equal, so two members of the same household with different telephones
12	 * (different keys) are both allowed.
13	 */
14	final class Identities {
15	
16	    private Identities() {
17	    }
18	
19	    /** The derived identity key (see {@link IdentityKeys#of(Owner)}). */
20	    static String identityKey(Owner owner) {
21	        return IdentityKeys.of(owner);
22	    }
23	
24	    /** Whether {@code candidate}'s whole identityKey already belongs to an existing owner. */
25	    static boolean isDuplicate(Collection<Owner> existing, Owner candidate) {
26	        String key = identityKey(candidate);
27	        return existing.stream().anyMatch(other -> key.equals(identityKey(other)));
28	    }
29	}
