2	
3	import java.util.Collection;
4	
5	import org.springframework.samples.petclinic.model.IdentityKeys;
6	import org.springframework.samples.petclinic.model.Owner;
7	
8	/**
9	 * Soft-match rule for owners: a candidate is a possible duplicate of an existing owner
10	 * when their identityKeys differ but their last names share a soundex code and they have
11	 * the same postcode, so it is created rather than rejected as a hard duplicate.
12	 */
13	final class PossibleDuplicates {
14	
15	    private PossibleDuplicates() {
16	    }
17	
18	    /**
19	     * The id of an existing owner {@code candidate} softly matches, or {@code null} if none.
20	     * A candidate that declares itself a household member ({@code sharesHousehold} true) is
21	     * never a suspected duplicate.
22	     */
23	    static Integer matchId(Collection<Owner> existing, Owner candidate, Boolean sharesHousehold) {
24	        if (Boolean.TRUE.equals(sharesHousehold)) {
25	            return null;
26	        }
27	        return existing.stream()
28	            .filter(other -> softMatch(other, candidate))
29	            .map(Owner::getId)
30	            .findFirst()
31	            .orElse(null);
32	    }
33	
34	    private static boolean softMatch(Owner a, Owner b) {
35	        String soundex = IdentityKeys.soundex(b.getLastName());
36	        return b.getPostcode() != null && b.getPostcode().equals(a.getPostcode())
37	            && !soundex.isEmpty() && soundex.equals(IdentityKeys.soundex(a.getLastName()))
38	            && !IdentityKeys.of(a).equals(IdentityKeys.of(b));
39	    }
40	}
