8	/**
9	 * De-duplicates an owner's customerCode against the codes already in use: the base
10	 * {@code <REGION>-<HASH8>} (see {@link CustomerCode}), suffixed with '-<n>' using the
11	 * smallest {@code n} of 2 or more that makes it unique.
12	 */
13	public final class CustomerCodes {
14	
15	    private CustomerCodes() {
16	    }
17	
18	    /** The unique customerCode for {@code owner} given the {@code existing} owners. */
19	    public static String uniqueFor(Owner owner, Collection<Owner> existing) {
20	        String base = CustomerCode.of(owner);
21	        Set<String> taken = existing.stream()
22	            .map(Owner::getCustomerCode)
23	            .filter(Objects::nonNull)
24	            .collect(Collectors.toSet());
25	        String code = base;
26	        for (int n = 2; taken.contains(code); n++) {
27	            code = base + "-" + n;
28	        }
29	        return code;
30	    }
31	}
