30	     * stripped. Returns {@code null} for a {@code null} input.
31	     */
32	    static String toE164(String raw) {
33	        if (raw == null) {
34	            return null;
35	        }
36	        boolean international = raw.trim().startsWith("+");
37	        String digits = raw.replaceAll("\\D", "");
38	        if (international) {
39	            return "+" + digits;
40	        }
41	        if (digits.startsWith("0")) {
42	            digits = digits.substring(1);
43	        }
44	        return "+61" + digits;
45	    }
46	}
