18	import java.util.Locale;
19	import java.util.Map;
20	
21	/**
22	 * Normalises a raw postal address: trims and collapses whitespace, upper-cases,
23	 * and expands common abbreviations ({@code ST->STREET}, {@code RD->ROAD},
24	 * {@code AVE->AVENUE}).
25	 */
26	final class PostalAddress {
27	
28	    private static final Map<String, String> ABBREVIATIONS = Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
29	
30	    private PostalAddress() {
31	    }
32	
33	    /**
34	     * The effective address: the composed structured lines when {@code line1} is
35	     * present (a single space joining a present {@code line2}), otherwise {@code flat}.
36	     * Both lines are expected to be already {@link #normalize(String) normalized}.
37	     */
38	    static String compose(String line1, String line2, String flat) {
39	        if (line1 == null || line1.isBlank()) {
40	            return flat;
41	        }
42	        return (line2 == null || line2.isBlank()) ? line1 : line1 + " " + line2;
43	    }
44	
45	    /** Returns {@code null} for a {@code null} input. */
46	    static String normalize(String raw) {
47	        if (raw == null) {
48	            return null;
49	        }
50	        StringBuilder sb = new StringBuilder();
51	        for (String word : raw.strip().split("\\s+")) {
52	            String upper = word.toUpperCase(Locale.ROOT);
53	            if (!sb.isEmpty()) {
54	                sb.append(' ');
55	            }
56	            sb.append(ABBREVIATIONS.getOrDefault(upper, upper));
57	        }
58	        return sb.toString();
59	    }
60	}
