3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HexFormat;
7	import java.util.Locale;
8	
9	/**
10	 * Derives an owner's {@code identityKey}: the lower-case hex SHA-256 of
11	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. Two owners
12	 * are the same identity exactly when this key is equal, so a shared surname/postcode with
13	 * a different telephone yields distinct keys (a soft match, not a hard duplicate).
14	 */
15	public final class IdentityKeys {
16	
17	    private IdentityKeys() {
18	    }
19	
20	    /** The identityKey for {@code owner} (64 lower-case hex characters). */
21	    public static String of(Owner owner) {
22	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone().strip();
23	        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase(Locale.ROOT);
24	        return sha256Hex("V2|" + telephone + "|" + email + "|" + soundex(owner.getLastName()));
25	    }
26	
27	    /** The American Soundex code of {@code name}, or {@code ""} when it has no letters. */
28	    public static String soundex(String name) {
29	        String letters = name == null ? "" : name.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
30	        if (letters.isEmpty()) {
31	            return "";
32	        }
33	        StringBuilder code = new StringBuilder().append(letters.charAt(0));
34	        char previous = digitOf(letters.charAt(0));
35	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
36	            char letter = letters.charAt(i);
37	            char digit = digitOf(letter);
38	            if (digit != '0' && digit != previous) {
39	                code.append(digit);
40	            }
41	            if (letter != 'H' && letter != 'W') {
42	                previous = digit;
43	            }
44	        }
45	        while (code.length() < 4) {
46	            code.append('0');
47	        }
48	        return code.toString();
49	    }
50	
51	    private static char digitOf(char letter) {
52	        return switch (letter) {
53	            case 'B', 'F', 'P', 'V' -> '1';
54	            case 'C', 'G', 'J', 'K', 'Q', 'S', 'X', 'Z' -> '2';
55	            case 'D', 'T' -> '3';
56	            case 'L' -> '4';
57	            case 'M', 'N' -> '5';
58	            case 'R' -> '6';
59	            default -> '0';
60	        };
61	    }
62	
63	    private static String sha256Hex(String value) {
64	        try {
65	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
66	            return HexFormat.of().formatHex(digest);
67	        }
68	        catch (NoSuchAlgorithmException e) {
69	            throw new IllegalStateException(e);
70	        }
71	    }
72	}
