1	package org.springframework.samples.petclinic.model;
2	
3	import java.nio.charset.StandardCharsets;
4	import java.security.MessageDigest;
5	import java.security.NoSuchAlgorithmException;
6	import java.util.HexFormat;
7	
8	/**
9	 * Builds an owner's unified memberId as {@code <REGION><FY><HASH8><CHK>}: REGION is the
10	 * region derived from the postcode (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099,
11	 * otherwise "UNKNOWN"), FY the two-digit registrationDate fiscal year, HASH8 the first 8
12	 * upper-case hex characters of SHA-256(normalizedTelephone + lastName), and CHK a single
13	 * Luhn check digit over the digits of {@code <REGION><FY><HASH8>}.
14	 */
15	public final class CustomerCode {
16	
17	    private CustomerCode() {
18	    }
19	
20	    /** Identity-version tag mixed into the region code inside the memberId (see class doc). */
21	    private static final String VERSION_TAG = "V2";
22	
23	    /** The memberId for {@code owner} (before any collision suffix). */
24	    public static String of(Owner owner) {
25	        String base = VERSION_TAG + region(owner)
26	            + String.format("%02d", FiscalYear.startYearOf(owner.getRegistrationDate()) % 100)
27	            + hash8(owner);
28	        return base + luhn(base);
29	    }
30	
31	    /** The region derived from {@code owner}'s postcode, or "UNKNOWN". */
32	    public static String region(Owner owner) {
33	        String postcode = owner.getPostcode();
34	        if (postcode != null && postcode.matches("\\d{4}")) {
35	            return switch (Integer.parseInt(postcode) / 100) {
36	                case 20 -> "NSW";
37	                case 30 -> "VIC";
38	                case 40 -> "QLD";
39	                default -> "UNKNOWN";
40	            };
41	        }
42	        return "UNKNOWN";
43	    }
44	
45	    private static String hash8(Owner owner) {
46	        byte[] digest;
47	        try {
48	            digest = MessageDigest.getInstance("SHA-256")
49	                .digest((owner.getTelephone() + owner.getLastName()).getBytes(StandardCharsets.UTF_8));
50	        } catch (NoSuchAlgorithmException ex) {
51	            throw new IllegalStateException(ex);
52	        }
53	        return HexFormat.of().withUpperCase().formatHex(digest).substring(0, 8);
54	    }
55	
56	    private static int luhn(String s) {
57	        int sum = 0;
58	        boolean dbl = true;
59	        for (int i = s.length() - 1; i >= 0; i--) {
60	            char c = s.charAt(i);
61	            if (c < '0' || c > '9') {
62	                continue;
63	            }
64	            int d = c - '0';
65	            if (dbl) {
66	                d *= 2;
67	                if (d > 9) {
68	                    d -= 9;
69	                }
70	            }
71	            sum += d;
72	            dbl = !dbl;
73	        }
74	        return (10 - (sum % 10)) % 10;
75	    }
76	}
